import getPointOnCircle from './getPointOnCircle'

interface GradientColor {
  offset: number
  color: string
}

interface Gradient {
  type: number
  palette: GradientColor[]
  angle: number
}

interface PatternTexture {
  repetition: string
  scale: number
}

interface Config {
  type: number
  color: string
  gradient: Gradient
  patternTexture: PatternTexture
  patternImage?: HTMLImageElement | null
}

export default function getCanvasStyle(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  config: Config,
  patternImage?: HTMLImageElement | null,
): string | CanvasGradient | CanvasPattern {
  // Solid
  if (config.type === 0) {
    return config.color
  }

  // Gradient
  if (config.type === 1) {
    const { type, palette, angle } = config.gradient
    let gradient: CanvasGradient
    const cx = x + width / 2
    const cy = y + height / 2
    const r = Math.max(width, height) / 2
    if (type === 0) {
      const startPoint = getPointOnCircle(cx, cy, r, angle + 180)
      const endPoint = getPointOnCircle(cx, cy, r, angle)
      gradient = ctx.createLinearGradient(
        startPoint.x,
        startPoint.y,
        endPoint.x,
        endPoint.y,
      )
    } else {
      gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, r)
    }

    palette.forEach((color) => {
      gradient.addColorStop(color.offset, color.color)
    })

    return gradient
  }

  const { repetition, scale } = config.patternTexture
  const image = patternImage ?? config.patternImage ?? null
  if (!image) {
    return 'rgba(0,0,0,0)'
  }

  const pattern = ctx.createPattern(image, repetition)
  if (!pattern) {
    return 'rgba(0,0,0,0)'
  }
  // TODO: Add trim translate and rotate.
  pattern.setTransform(new DOMMatrix().scale(scale).translate(x, y))
  return pattern
}
